"use strict";(self.webpackChunksalat_e_mustaqeem_client=self.webpackChunksalat_e_mustaqeem_client||[]).push([[9282],{99282:a=>{a.exports=JSON.parse('{"meta":{"title":"Ejen AI - iMuslim Life","description":"Tanya Claude, ChatGPT, Gemini atau Copilot tentang waktu solat hari ini, arah kiblat dan tarikh Hijrah. Sambungkan pelayan MCP percuma kami dalam seminit, tanpa kunci API."},"chip":"Baharu: pelayan MCP","h1":"Waktu solat untuk pembantu AI anda","lede":"Sambungkan Claude, ChatGPT, Gemini atau Copilot ke pelayan waktu solat Muslim Companion. Pembantu anda kemudian menjawab dengan waktu yang benar-benar dikira untuk bandar dan kaedah anda, bukan tekaan.","copy":"Salin","copied":"Disalin","toolsH2":"Apa yang boleh dilakukan pembantu anda","toolsSub":"Enam alat baca sahaja. Waktu dikira mengikut zon waktu tempat itu sendiri, dengan kaedah pengiraan dan mazhab Asar pilihan anda.","tools":{"prayer":{"title":"Waktu solat untuk mana-mana hari","text":"Subuh, Syuruk, Zohor, Asar, Maghrib dan Isyak untuk sesuatu tempat dan tarikh, dalam waktu tempatan, bersama tarikh Hijrah."},"next":{"title":"Solat seterusnya","text":"Solat mana yang seterusnya, waktunya dan berapa minit lagi."},"find":{"title":"Cari tempat","text":"Menukar bandar atau alamat kepada koordinat dan zon waktu."},"hijri":{"title":"Tarikh Hijrah","text":"Tarikh Islam bagi mana-mana tarikh Masihi."},"qibla":{"title":"Arah kiblat","text":"Arah Kaabah dari mana-mana tempat, dalam darjah dan arah kompas."},"methods":{"title":"Kaedah pengiraan","text":"ISNA, Liga Dunia Islam, Umm al-Qura, Karachi dan 11 lagi, serta Asar Hanafi atau standard."}},"setupH2":"Cara menyediakan","tabDevelopers":"Pembangun","claude":{"s1":"Di <b>claude.ai</b> atau dalam <b>Claude Desktop</b>, buka <b>Settings \u2192 Connectors</b>.","s2":"Pilih <b>Add custom connector</b>. Namakan <b>Muslim Companion</b> dan tampal URL pelayan di bawah.","s3":"Simpan. Dalam sembang, hidupkan penyambung (dari menu alat) dan tanya: <i>\u201cBila Maghrib di Toronto hari ini?\u201d</i>","note":"Penyambung tersuai bergantung pada pelan Claude anda. Untuk Claude Code, jalankan arahan di bawah sebagai ganti."},"chatgpt":{"s1":"Dalam ChatGPT, buka <b>Settings \u2192 Apps & Connectors</b>, kemudian <b>Advanced settings</b>, dan hidupkan <b>Developer mode</b>.","s2":"Pilih <b>Create</b> (penyambung baharu). Namakan <b>Muslim Companion</b>, tampal URL pelayan di bawah dan pilih <b>No authentication</b>.","s3":"Dalam sembang baharu, tambah penyambung dan tanya: <i>\u201cApakah waktu solat hari ini di London, Asar Hanafi?\u201d</i>","note":"Penyambung mod pembangun bergantung pada pelan ChatGPT anda, dan nama menu boleh berubah antara versi."},"gemini":{"s1":"Buka <b>~/.gemini/settings.json</b> (cipta jika belum ada).","s2":"Tambah entri <b>muslim-companion</b> di bawah ke dalam <b>mcpServers</b>, kemudian mulakan semula Gemini CLI.","s3":"Jalankan <b>/mcp</b> untuk memastikan ia bersambung, kemudian tanya tentang waktu solat."},"vscode":{"s1":"Dalam projek anda, cipta <b>.vscode/mcp.json</b> (atau jalankan <b>MCP: Add Server</b> dari Command Palette dan pilih <b>HTTP</b>).","s2":"Tampal konfigurasi di bawah dan klik <b>Start</b> di atas entri pelayan.","s3":"Dalam Copilot Chat, tukar ke mod <b>Agent</b> dan tanya tentang waktu solat."},"dev":{"s1":"Mana-mana klien MCP boleh bersambung: pelayan menggunakan <b>Streamable HTTP</b>, tanpa keadaan dan tidak memerlukan kunci API.","s2":"Panggil alat dengan permintaan JSON-RPC <b>POST</b>, seperti contoh di bawah.","s3":"Baca <a>llms.txt</a> untuk gambaran ringkas yang ditulis untuk model bahasa.","note":"Had: 60 permintaan seminit dan 600 sejam bagi setiap klien. Sila simpan waktu sehari dalam cache daripada bertanya berulang kali."},"tryAsk":"Cuba tanya: <i>\u201cBila Subuh esok di Orlando?\u201d</i> \xb7 <i>\u201cKe arah mana kiblat dari Karachi?\u201d</i> \xb7 <i>\u201cApakah tarikh Hijrah hari ini?\u201d</i> \xb7 <i>\u201cBerapa lama lagi Asar di Toronto, Hanafi?\u201d</i>","privacyH":"Data awam sahaja","privacy":"Pelayan hanya menyediakan maklumat awam: waktu solat, tarikh Hijrah, arah kiblat dan kaedah pengiraan. Ia tidak memerlukan akaun dan tidak boleh melihat atau mengubah apa-apa dalam tetapan Muslim Companion anda. Ciri yang bertindak bagi pihak anda, seperti membaca jadual Azan anda sendiri, akan datang kemudian dan sentiasa memerlukan anda log masuk dan memberi kebenaran. Lihat <a>Dasar Privasi</a> kami.","alexaCta":"Muslim Companion untuk Alexa"}')}}]);